def make_icon_uri(img_path, size=64, white_cutoff=235):
    from PIL import Image
    img = Image.open(img_path).convert("RGBA"); px = img.load()
    for y in range(img.height):
        for x in range(img.width):
            r, g, b, a = px[x, y]
            if r >= white_cutoff and g >= white_cutoff and b >= white_cutoff:
                px[x, y] = (r, g, b, 0)
    bbox = img.getchannel("A").point(lambda v: 255 if v > 10 else 0).getbbox()
    if bbox: img = img.crop(bbox)
    side = max(img.size); sq = Image.new("RGBA", (side, side), (0, 0, 0, 0))
    sq.paste(img, ((side - img.width) // 2, (side - img.height) // 2), img)
    buf = io.BytesIO(); sq.resize((size, size), Image.LANCZOS).save(buf, "PNG", optimize=True)
    return "data:image/png;base64," + base64.b64encode(buf.getvalue()).decode()

def build_html(favicon=None):
    html = TEMPLATE
    local_chart = Path(__file__).with_name("vendor-chart.umd.min.js")
    if local_chart.exists():
        chart_js = local_chart.read_text(encoding="utf-8")
        html = html.replace(
            '<script src="https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.min.js"></script>',
            '<script>' + chart_js + '</script>'
        )
    for name, payload in (("D", DATA_D), ("V", DATA_V), ("XB", DATA_XB), ("GEO", DATA_GEO)):
        html = html.replace("/*@@%s@@*/;" % name, "%s;" % payload)
    if favicon:
        uri = make_icon_uri(favicon)
        html = re.sub(r'(<link rel="icon"[^>]*href=")[^"]*(")', lambda m: m.group(1) + uri + m.group(2), html, count=1)
    return html

def main():
    ap = argparse.ArgumentParser(description="Build the Egypt 2021 dashboard (single HTML file)")
    ap.add_argument("-o", "--out", default="Egypt_2021_Dashboard.html")
    ap.add_argument("--favicon", help="optional ankh image (png/jpg) to use as the tab icon")
    ap.add_argument("--open", action="store_true", help="open the result in the browser")
    a = ap.parse_args()
    out = Path(a.out); out.write_text(build_html(a.favicon), encoding="utf-8")
    print("Done ->", out.resolve(), "(%.0f KB)" % (out.stat().st_size / 1024))
    if a.open: webbrowser.open(out.resolve().as_uri())

if __name__ == "__main__":
    sys.exit(main())

